/**
 * Bill-splitting math. Pure, no I/O, no Node-only APIs — the browser page
 * imports this same file (served at /split.js), so keep it that way.
 *
 * All money math is done in whole cents to avoid floating-point drift.
 */

/**
 * @typedef {{ ok: true, tip: number, total: number, perPerson: number }} SplitOk
 *   Amounts are in currency units (e.g. dollars), rounded to cents.
 * @typedef {{ ok: false, field: 'bill' | 'tipPercent' | 'people', message: string }} SplitError
 *   `field` names the first bad input so the UI can point at it.
 */

/**
 * Split a bill between people.
 *
 * - Tip = bill × tip% , rounded to the nearest cent.
 * - Total = bill + tip.
 * - Per person = total ÷ people, rounded UP to the cent, so the group never
 *   comes up short (e.g. 100 ÷ 3 → 33.34).
 *
 * Accepts numbers or the raw strings from form fields. Never throws: bad or
 * empty input returns `{ ok: false, field, message }`.
 *
 * @param {{ bill?: number|string, tipPercent?: number|string, people?: number|string }} [input]
 * @returns {SplitOk | SplitError}
 */
export function splitBill({ bill, tipPercent, people } = {}) {
  const billValue = toNumber(bill);
  if (billValue === null) return fail('bill', 'Enter the bill amount.');
  if (billValue < 0) return fail('bill', 'The bill can’t be negative.');

  const tipValue = toNumber(tipPercent);
  if (tipValue === null) return fail('tipPercent', 'Enter a tip percentage.');
  if (tipValue < 0) return fail('tipPercent', 'The tip can’t be negative.');

  const peopleValue = toNumber(people);
  if (peopleValue === null) return fail('people', 'Enter the number of people.');
  if (!Number.isInteger(peopleValue) || peopleValue < 1) {
    return fail('people', 'Number of people must be a whole number, 1 or more.');
  }

  const billCents = Math.round(billValue * 100);
  const tipCents = Math.round((billCents * tipValue) / 100);
  const totalCents = billCents + tipCents;
  const perPersonCents = Math.ceil(totalCents / peopleValue);

  return {
    ok: true,

==> src/split.test.js <==
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { splitBill } from './split.js';

test('splits a normal bill evenly', () => {
  assert.deepEqual(splitBill({ bill: 100, tipPercent: 20, people: 4 }), {
    ok: true,
    tip: 20,
    total: 120,
    perPerson: 30,
  });
});

test('accepts string input straight from form fields', () => {
  assert.deepEqual(splitBill({ bill: ' 50 ', tipPercent: '10', people: '2' }), {
    ok: true,
    tip: 5,
    total: 55,
    perPerson: 27.5,
  });
});

test('zero tip is allowed', () => {
  assert.deepEqual(splitBill({ bill: 30, tipPercent: 0, people: 3 }), {
    ok: true,
    tip: 0,
    total: 30,
    perPerson: 10,
  });
});

test('one person pays the whole total', () => {
  const r = splitBill({ bill: 42.5, tipPercent: 15, people: 1 });
  assert.equal(r.ok, true);
  assert.equal(r.tip, 6.38); // 6.375 rounds to nearest cent
  assert.equal(r.total, 48.88);
  assert.equal(r.perPerson, 48.88);
});

test('tip is rounded to the nearest cent', () => {
  const r = splitBill({ bill: 10.01, tipPercent: 15, people: 1 });
  assert.equal(r.tip, 1.5); // 1.5015 -> 1.50
  assert.equal(r.total, 11.51);
});

test('avoids floating point drift (0.1 + 0.2 style)', () => {
  const r = splitBill({ bill: 0.1, tipPercent: 200, people: 1 });
  assert.equal(r.tip, 0.2);
  assert.equal(r.total, 0.3);
});

